// DSHA_TOOL_DISPATCH_IDENTITY_RC22_V1: validate the whole batch before executor side effects.
function assertDshaToolCallBatch(toolCalls) {
	if (toolCalls.some(block => !(typeof block.id === "string" && block.id.trim() !== "" && typeof block.name === "string" && block.name.trim() !== ""))) throw new LlmError("DSHA_INVALID_TOOL_CALL: missing name/id; this step was not dispatched. No automatic replay.", "INVALID_RESPONSE");
}
//#region lib/types/inbox.js

// DSHA_TOOL_FINISH_IDENTITY_RC22_V1: malformed batches are diagnostic text, never replayable calls.
const assembledBlocks = live.blocks();
const invalidIdentity = assembledBlocks.some(block => block.type === "tool-call" && !(typeof block.id === "string" && block.id.trim() !== "" && typeof block.name === "string" && block.name.trim() !== ""));
const message = createAssistantMessage({
	content: assembledBlocks.map(block => invalidIdentity && block.type === "tool-call" ? { type: "text", text: "[DSHA_INVALID_TOOL_CALL] Missing tool name/id in this batch. No tool in this step was executed; no automatic replay." } : block),
